</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
The leader of some very secretive organization has decided to invite all other members to a meeting. All members of the organization live in the same town which can be represented as $$$n$$$ crossroads connected by $$$m$$$ two-directional streets. The meeting will be held in the leader's house near the crossroad $$$1$$$. There are $$$k$$$ members of the organization invited to the meeting; $$$i$$$-th of them lives near the crossroad $$$a_i$$$. All members of the organization receive the message about the meeting at the same moment and start moving to the location where the meeting is held. In the beginning of each minute each person is located at some crossroad. He or she can either wait a minute at this crossroad, or spend a minute to walk from the current crossroad along some street to another crossroad (obviously, it is possible to start walking along the street only if it begins or ends at the current crossroad). In the beginning of the first minute each person is at the crossroad where he or she lives. As soon as a person reaches the crossroad number $$$1$$$, he or she immediately comes to the leader's house and attends the meeting.Obviously, the leader wants all other members of the organization to come up as early as possible. But, since the organization is very secretive, the leader does not want to attract much attention. Let's denote the discontent of the leader as follows  initially the discontent is $$$0$$$;  whenever a person reaches the crossroad number $$$1$$$, the discontent of the leader increases by $$$c \cdot x$$$, where $$$c$$$ is some fixed constant, and $$$x$$$ is the number of minutes it took the person to reach the crossroad number $$$1$$$;  whenever $$$x$$$ members of the organization walk along the same street at the same moment in the same direction, $$$dx^2$$$ is added to the discontent, where $$$d$$$ is some fixed constant. This is not cumulative: for example, if two persons are walking along the same street in the same direction at the same moment, then $$$4d$$$ is added to the discontent, not $$$5d$$$. Before sending a message about the meeting, the leader can tell each member of the organization which path they should choose and where they should wait. Help the leader to establish a plan for every member of the organization so they all reach the crossroad $$$1$$$, and the discontent is minimized.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class Input {
        private final byte[] buf = new byte[1 << 15];
        private int ptr, len;
        private final InputStream is;

        Input(InputStream s) { is = s; }

        private int next() throws IOException {
            if (ptr >= len) {
                len = is.read(buf);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            while ((c = next()) <= 32) if (c == -1) return -1;
            int x = 0;
            while (c > 32) {
                x = x * 10 + c - '0';
                c = next();
            }
            return x;
        }
    }

    Input in;

    public static void main(String[] args) {
        CF1187G solver = new CF1187G();
        solver.in = new Input(System.in);
        solver.execute();
        solver.flush();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] adj;
    int N, M;
    int[] dist, lvl;
    int[] u, v, uv;
    int[] cap, origCost, redCost;
    int[] flow;

    void build(int n, int m) {
        N = n;
        M = m;
        adj = new ArrayList[N];
        for (int i = 0; i < N; i++) adj[i] = new ArrayList<>();
        dist = new int[N];
        lvl = new int[N];
        u = new int[M];
        v = new int[M];
        uv = new int[M];
        cap = new int[M];
        origCost = new int[M];
        redCost = new int[M];
        flow = new int[M];
    }

    void add(int a, int b, int c, int cost) {
        int idx = M++;
        u[idx] = a;
        v[idx] = b;
        uv[idx] = a ^ b;
        origCost[idx] = cost;
        redCost[idx] = cost;
        cap[idx] = c;
        flow[idx] = c;
        adj[a].add(idx);
        adj[b].add(idx ^ 1);
    }

    boolean findPath(int s, int t) {
        Arrays.fill(dist, INF);
        Arrays.fill(lvl, 0);
        dist[s] = 0;

        TreeSet<Integer> pq = new TreeSet<>((x, y) -> {
            if (dist[x] != dist[y]) return dist[x] - dist[y];
            if (lvl[x] != lvl[y]) return lvl[x] - lvl[y];
            return x - y;
        });
        pq.add(s);

        while (!pq.isEmpty()) {
            int node = pq.pollFirst();
            int nextLvl = lvl[node] + 1;

            for (int e : adj[node]) {
                if (cap[e] <= 0) continue;
                int idx = e >> 1;
                int cost = (e & 1) == 0 ? redCost[idx] : -redCost[idx];
                int nd = dist[node] + cost;
                int to = node ^ uv[idx];

                if (nd < dist[to] || (nd == dist[to] && lvl[to] > nextLvl)) {
                    if (dist[to] != INF) pq.remove(to);
                    dist[to] = nd;
                    lvl[to] = nextLvl;
                    pq.add(to);
                }
            }
        }
        return dist[t] != INF;
    }

    int dfs(int node, int sink, int f) {
        if (node == sink || f == 0) return f;
        int nextLvl = lvl[node] + 1;

        for (int e : adj[node]) {
            if (cap[e] <= 0) continue;
            int idx = e >> 1;
            int cost = (e & 1) == 0 ? redCost[idx] : -redCost[idx];
            int to = node ^ uv[idx];

            if (dist[to] == dist[node] + cost && lvl[to] == nextLvl) {
                int pushed = dfs(to, sink, Math.min(f, cap[e]));
                if (pushed > 0) {
                    cap[e] -= pushed;
                    cap[e ^ 1] += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    int solve(int s, int t) {
        System.arraycopy(origCost, 0, redCost, 0, M);
        int total = 0;

        while (findPath(s, t)) {
            while (dfs(s, t, INF) > 0) {}

            for (int i = 0; i < M; i++) {
                if (dist[u[i]] != INF && dist[v[i]] != INF) {
                    redCost[i] += dist[u[i]] - dist[v[i]];
                }
            }
        }

        for (int i = 0; i < M; i++) {
            total += origCost[i] * (cap[i ^ 1]);
        }
        return total;
    }

    void execute() {
        try {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();
            int c = in.nextInt();
            int d = in.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) special[i] = in.nextInt() - 1;

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                g[a].add(b);
                g[b].add(a);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);
            build(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int neighbor : g[i]) {
                        int v = neighbor * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            add(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    add(u, v, k, i == 0 ? 0 : c);
                }
            }

            int source = totalNodes - 1;
            for (int i = 0; i < k; i++) {
                add(source, special[i] * T + 0, 1, 0);
            }

            int sink = 0 * T + T - 1;
            println(solve(source, sink));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
